// ============================================================
// [SEL] Selecionar PDFs
// Cruza os PDFs do Drive com o registro persistente e decide, SEM baixar
// nada, quais ainda precisam de trabalho nesta execucao.
//
// Versao do arquivo = md5Checksum do Drive (muda quando o conteudo muda).
// O mesmo PDF/versao nunca e reenviado ao mesmo destino: a chave do
// registro e  file_id | versao | destino.
// ============================================================
const cfg = $('[CFG] Configuração').first().json;
const pdfsBrutos = $('[DRIVE] Listar PDFs').all();
falhaDoDrive(pdfsBrutos, 'listagem de PDFs');
const pastas = $('[DRIVE] Consulta de PDFs').first().json.pastas || {};

// ----- registro atual, agrupado por arquivo+versao -----
const porVersao = {};
for (const it of $input.all()) {
  const r = it.json || {};
  if (!r.chave || !r.file_id || String(r.chave).startsWith('__')) continue;
  const k = r.file_id + '|' + r.versao;
  (porVersao[k] = porVersao[k] || []).push(r);
}

// Sobe na arvore ate a pasta filha direta da raiz: ela define o template.
function categoriaDe(pastaId) {
  const caminho = [];
  let id = pastaId;
  for (let n = 0; n < 10 && id && id !== cfg.pasta_raiz_id; n++) {
    const p = pastas[id];
    if (!p) return { categoriaId: '', categoria: '', caminho: '(pasta fora da arvore)' };
    caminho.unshift(p.nome);
    if (p.pai === cfg.pasta_raiz_id) return { categoriaId: id, categoria: p.nome, caminho: caminho.join(' / ') };
    id = p.pai;
  }
  return { categoriaId: '', categoria: '', caminho: '(raiz)' };
}

const cont = { pdfs_no_drive: 0, ja_aceitos: 0, incertos: 0, em_andamento: 0, tentativas_esgotadas: 0,
  bloqueados_recentes: 0, anteriores_ao_corte: 0, fora_do_teste: 0, candidatos: 0, adiados: 0 };
const corte = cfg.ignorar_criados_antes ? Date.parse(cfg.ignorar_criados_antes) : null;
const vistos = new Set();
const candidatos = [];

for (const it of pdfsBrutos) {
  const f = it.json || {};
  if (!f.id || vistos.has(f.id)) continue;
  vistos.add(f.id);
  cont.pdfs_no_drive++;
  if (cfg.arquivos_teste.length && !cfg.arquivos_teste.includes(f.id)) { cont.fora_do_teste++; continue; }
  if (corte && Date.parse(f.createdTime) < corte) { cont.anteriores_ao_corte++; continue; }

  const versao = txt(f.md5Checksum) || ('mod-' + txt(f.modifiedTime) + '-' + txt(f.size));
  const linhas = porVersao[f.id + '|' + versao] || [];
  const doModo = linhas.filter((r) => r.modo === cfg.modo);

  if (doModo.some((r) => r.estado === 'ACEITO')) { cont.ja_aceitos++; continue; }
  if (doModo.some((r) => r.estado === 'INCERTO')) { cont.incertos++; continue; }

  const pastaId = (Array.isArray(f.parents) && f.parents[0]) || '';
  const cat = categoriaDe(pastaId);
  const modelo = cat.categoriaId ? (cfg.modelos[cat.categoriaId] || null) : null;
  let modeloErro = '';
  if (!cat.categoria) modeloErro = 'PASTA_SEM_MODELO: o PDF esta fora das pastas de categoria (' + cat.caminho + ')';
  else if (!modelo) modeloErro = 'PASTA_SEM_MODELO: a pasta "' + cat.categoria + '" (id ' + cat.categoriaId + ') nao esta no mapa de templates';
  else if (!modelo.template_id) modeloErro = 'SEM_TEMPLATE: ' + (modelo.motivo || 'pasta sem template');

  const comum = {
    file_id: f.id, versao, arquivo: txt(f.name), pasta: cat.caminho, categoria: cat.categoria, categoria_id: cat.categoriaId, pasta_id: pastaId,
    template_id: modelo && modelo.template_id ? modelo.template_id : null,
    template_nome: modelo && modelo.template_nome ? modelo.template_nome : '',
    modelo_erro: modeloErro,
    link_drive: txt(f.webViewLink) || ('https://drive.google.com/file/d/' + f.id + '/view'),
    criado_em: txt(f.createdTime), tamanho: Number(f.size) || 0
  };

  // Envio que comecou e nao terminou (queda no meio): nao reenviar as cegas.
  const travado = doModo.find((r) => r.estado === 'ENVIANDO');
  if (travado) {
    if (idadeHoras(travado.atualizado_em) * 60 < cfg.envio_travado_minutos) { cont.em_andamento++; continue; }
    const registro = linhaRegistro(travado, {
      estado: 'INCERTO', execucao: cfg.execucao, atualizado_em: agoraISO(),
      erro: 'Envio iniciado em ' + horaLocal(travado.atualizado_em) + ' sem resposta registrada (execucao ' +
        travado.execucao + '). A mensagem pode ter saido: conferir no painel Maxbot antes de reenviar.'
    });
    candidatos.push({ json: Object.assign(comum, { acao_previa: 'VERIFICAR', registro, motivo_alerta: registro.erro }) });
    continue;
  }
  if (doModo.some((r) => r.estado === 'ERRO_ENVIO' && Number(r.tentativas) >= cfg.max_tentativas)) {
    cont.tentativas_esgotadas++; continue;
  }
  const bloqueio = linhas.find((r) => r.estado === 'BLOQUEADO');
  if (bloqueio && idadeHoras(bloqueio.atualizado_em) < cfg.reavaliar_bloqueados_horas) { cont.bloqueados_recentes++; continue; }

  candidatos.push({ json: Object.assign(comum, { acao_previa: 'PROCESSAR' }) });
}

// Verificacoes primeiro (nao baixam nada), depois os mais antigos.
candidatos.sort((a, b) => (a.json.acao_previa === b.json.acao_previa ? 0 : a.json.acao_previa === 'VERIFICAR' ? -1 : 1) ||
  String(a.json.criado_em).localeCompare(String(b.json.criado_em)));
const lote = candidatos.slice(0, cfg.max_pdfs);
cont.candidatos = lote.length;
cont.adiados = candidatos.length - lote.length;

if (!lote.length) return [{ json: { sem_candidatos: true, resumo_selecao: cont } }];
lote[0].json.resumo_selecao = cont;
return lote;

