// ---------- CPF / CNPJ ----------
function cpfValido(d) {
  if (!/^\d{11}$/.test(d) || /^(\d)\1{10}$/.test(d)) return false;
  for (let t = 9; t < 11; t++) {
    let s = 0;
    for (let i = 0; i < t; i++) s += Number(d[i]) * (t + 1 - i);
    if (((s * 10) % 11) % 10 !== Number(d[t])) return false;
  }
  return true;
}
// Aceita o CNPJ alfanumerico (12 posicoes 0-9/A-Z + 2 DV numericos):
// o valor de cada caractere e (codigo ASCII - 48), que para digitos
// coincide com o CNPJ numerico tradicional.
function cnpjValido(c) {
  if (!/^[0-9A-Z]{12}\d{2}$/.test(c) || /^(\d)\1{13}$/.test(c)) return false;
  const dv = (base) => {
    const pesos = base.length === 12 ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2] : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
    let s = 0;
    for (let i = 0; i < base.length; i++) s += (base.charCodeAt(i) - 48) * pesos[i];
    const r = s % 11;
    return r < 2 ? 0 : 11 - r;
  };
  return dv(c.slice(0, 12)) === Number(c[12]) && dv(c.slice(0, 13)) === Number(c[13]);
}
function formatarDoc(d) {
  if (/^[0-9A-Z]{14}$/.test(d)) return d.replace(/^(.{2})(.{3})(.{3})(.{4})(.{2})$/, '$1.$2.$3/$4-$5');
  if (/^\d{11}$/.test(d)) return d.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, '$1.$2.$3-$4');
  if (/^\d{8}$/.test(d)) return d.replace(/^(\d{2})(\d{3})(\d{3})$/, '$1.$2.$3') + ' (raiz)';
  return d;
}

// Celula da coluna de documento da planilha -> documento normalizado.
// Numero vindo do Sheets perde zeros a esquerda (ex.: 01234567000189 vira
// 1234567000189). Eles sao repostos pelo tamanho, e so fica o que passa no
// digito verificador. Notacao cientifica ja perdeu digitos: descartada.
function docDaCelula(v) {
  if (v === null || v === undefined || v === '') return '';
  let s;
  if (typeof v === 'number') {
    if (!Number.isInteger(v) || v <= 0) return '';
    s = String(v);
  } else {
    s = txt(v);
    if (/\d[.,]?\d*e\+?\d+$/i.test(s)) return '';
  }
  s = s.toUpperCase().replace(/[^0-9A-Z]/g, '');
  if (!s) return '';
  if (/^\d+$/.test(s)) {
    if (s.length > 14) return '';
    if (s.length === 14 || s.length >= 12) return cnpjValido(s.padStart(14, '0')) ? s.padStart(14, '0') : '';
    const cpf = s.padStart(11, '0');
    if (cpfValido(cpf)) return cpf;
    const cnpj = s.padStart(14, '0');
    return cnpjValido(cnpj) ? cnpj : '';
  }
  return s.length === 14 && cnpjValido(s) ? s : '';
}

