// [ID] Identificar cliente
//
// Regra: o titular e quem o CONTEUDO do PDF aponta E existe na planilha
// geral. Nunca "o primeiro CNPJ do texto".
//
//  1. Colhe todo CPF/CNPJ valido do texto (digito verificador conferido),
//     e a raiz de 8 digitos logo abaixo de "CPF/CNPJ do Empregador"
//     (a guia do FGTS Digital so traz a raiz).
//  2. Descarta os documentos do escritorio (ENVPDF_CNPJS_IGNORADOS).
//  3. Casa o resto com a planilha. Documentos que levam ao MESMO telefone
//     sao o mesmo cliente (ex.: CNPJ do MEI + CPF do dono).
//  4. Um cliente so -> segue. Mais de um -> so segue se exatamente um
//     aparece como pagador/contribuinte/empregador e os outros nao.
//  5. Duvida (titular so aparece como beneficiario/emitente, pagador fora
//     da planilha, nome do arquivo aponta outro cliente) -> bloqueia.
//
// O rotulo e procurado na mesma linha, antes do valor, e na linha
// anterior: o extrator do n8n as vezes separa rotulo e valor, e por isso
// o papel so DESEMPATA; quem decide e a planilha.
// ============================================================
const cfg = $('[CFG] Configuração').first().json;
const base = $('[BASE] Indexar clientes').first().json;
const loop = $('[LOOP] Um PDF por vez').first().json;
const entrada = $input.first().json || {};
const extraido = $('[PDF] Extrair texto').first().json || {};
const baixado = $('[DRIVE] Baixar PDF').first().json || {};

// Trava contra dado de outro PDF: tudo aqui tem de ser do item do laco.
for (const [nome, j] of [['entrada', entrada], ['extrator', extraido], ['download', baixado]]) {
  if (j.file_id && j.file_id !== loop.file_id) {
    throw new Error('Dados de ' + nome + ' pertencem a ' + j.file_id + ', mas o laco esta em ' + loop.file_id);
  }
}

const PAPEL_POS = ['PAGADOR', 'SACADO', 'CONTRIBUINTE', 'EMPREGADOR', 'TOMADOR', 'CLIENTE', 'DEVEDOR',
  'DESTINATARIO', 'ADQUIRENTE'];
const PAPEL_NEG = ['BENEFICIARIO', 'BENECIARIO', 'BENE CIARIO', 'CEDENTE', 'EMITENTE', 'PRESTADOR', 'SACADOR',
  'AVALISTA', 'RECEBEDOR', 'FAVORECIDO', 'INSTITUICAO FINANCEIRA'];

function papelDe(contexto) {
  let papel = 'NEUTRO';
  let pos = -1;
  for (const p of PAPEL_POS) { const i = contexto.lastIndexOf(p); if (i > pos) { pos = i; papel = 'POS'; } }
  // >= : "SACADOR" contem "SACADO" na mesma posicao, e deve valer o negativo
  for (const p of PAPEL_NEG) { const i = contexto.lastIndexOf(p); if (i >= 0 && i >= pos) { pos = i; papel = 'NEG'; } }
  return papel;
}

const PADROES = [
  { tipo: 'CNPJ', re: /(?<![0-9A-Za-z])([0-9A-Za-z]{2}\.[0-9A-Za-z]{3}\.[0-9A-Za-z]{3}\/[0-9A-Za-z]{4}-\d{2})(?![0-9])/g },
  { tipo: 'CNPJ', re: /(?<![0-9])(\d{14})(?![0-9])/g },
  { tipo: 'CPF', re: /(?<![0-9.])(\d{3}\.\d{3}\.\d{3}-\d{2})(?![0-9])/g },
  // 11 digitos soltos aparecem em codigo de barras: so com "CPF" por perto
  { tipo: 'CPF', re: /(?<![0-9])(\d{11})(?![0-9])/g, exigeRotulo: /CPF/ }
];

function colherDocumentos(texto) {
  const achados = [];
  const linhas = String(texto || '').split(/\r?\n/);
  for (let n = 0; n < linhas.length; n++) {
    const linha = linhas[n];
    const anterior = n > 0 ? maiusculo(linhas[n - 1]) : '';
    for (const p of PADROES) {
      p.re.lastIndex = 0;
      let m;
      while ((m = p.re.exec(linha)) !== null) {
        const contexto = anterior + ' \n ' + maiusculo(linha.slice(0, m.index));
        if (p.exigeRotulo && !p.exigeRotulo.test(contexto.slice(-40))) continue;
        const valor = m[1].toUpperCase().replace(/[^0-9A-Z]/g, '');
        const ok = p.tipo === 'CNPJ' ? cnpjValido(valor) : cpfValido(valor);
        if (ok) achados.push({ tipo: p.tipo, valor, papel: papelDe(contexto), linha: n + 1 });
      }
    }
    // FGTS Digital: "CPF/CNPJ do Empregador" e, na linha seguinte, so a raiz.
    const raiz = linha.match(/^\s*(\d{2}\.\d{3}\.\d{3})\s*$/);
    if (raiz && /EMPREGADOR/.test(anterior)) {
      achados.push({ tipo: 'RAIZ', valor: raiz[1].replace(/\D/g, ''), papel: 'POS', linha: n + 1 });
    }
  }
  return achados;
}

function resolverTelefone(linhasPlanilha) {
  const comTel = linhasPlanilha.filter((l) => txt(l.tel));
  if (!comTel.length) return { ok: false, codigo: 'TELEFONE_AUSENTE', motivo: 'o cadastro na planilha nao tem telefone' };
  const avaliados = comTel.map((l) => ({ l, t: normalizarTelefone(l.tel) }));
  const validos = avaliados.filter((x) => x.t.ok);
  const distintos = [...new Set(validos.map((x) => x.t.numero))];
  if (distintos.length > 1) {
    return { ok: false, codigo: 'TELEFONES_DIVERGENTES', motivo: 'linhas do mesmo documento com telefones diferentes (' + distintos.join(', ') + ')' };
  }
  if (!distintos.length) {
    const t = avaliados[0].t;
    return { ok: false, codigo: t.motivo, motivo: 'telefone "' + txt(t.bruto) + '" na linha ' + avaliados[0].l.linha + ' (' + (t.detalhe || t.motivo) + ')' };
  }
  const escolhida = validos.find((x) => x.t.numero === distintos[0]).l;
  return { ok: true, telefone: distintos[0], nome: escolhida.nome, linha: escolhida.linha, doc_linha: escolhida.doc || '' };
}

function identificar(texto, nomeArquivo) {
  const ignorados = new Set(cfg.cnpjs_ignorados);
  const raizesIgnoradas = new Set(cfg.cnpjs_ignorados.filter((d) => d.length === 14).map((d) => d.slice(0, 8)));
  const achados = colherDocumentos(texto);
  const docs = new Map();
  let viuEscritorio = false;
  for (const a of achados) {
    if (ignorados.has(a.valor) || (a.tipo === 'RAIZ' && raizesIgnoradas.has(a.valor))) { viuEscritorio = true; continue; }
    const d = docs.get(a.valor) || { tipo: a.tipo, valor: a.valor, papeis: new Set(), linhas: [] };
    d.papeis.add(a.papel);
    d.linhas.push(a.linha);
    docs.set(a.valor, d);
  }
  const lista = [...docs.values()];
  const diag = lista.map((d) => formatarDoc(d.valor) + ' [' + [...d.papeis].join('/') + ']');

  if (!lista.length) {
    return viuEscritorio
      ? { ok: false, codigo: 'SO_DOCUMENTO_DO_ESCRITORIO', motivo: 'o texto so contem o CNPJ do escritorio; nenhum CPF/CNPJ de cliente', diag }
      : { ok: false, codigo: 'NENHUM_CPF_CNPJ', motivo: 'nenhum CPF/CNPJ valido encontrado no conteudo do PDF', diag };
  }

  // casa cada documento com a planilha e agrupa por pessoa (telefone)
  const grupos = new Map();
  const naoCasados = [];
  for (const d of lista) {
    const linhasPlanilha = d.tipo === 'RAIZ' ? (base.porRaiz[d.valor] || []) : (base.porDoc[d.valor] || []);
    if (!linhasPlanilha.length) { naoCasados.push(d); continue; }
    const res = resolverTelefone(linhasPlanilha);
    const chave = res.ok ? 'TEL:' + res.telefone : 'DOC:' + d.valor;
    const g = grupos.get(chave) || { docs: [], papeis: new Set(), res };
    g.docs.push(d);
    d.papeis.forEach((p) => g.papeis.add(p));
    grupos.set(chave, g);
  }
  const gs = [...grupos.values()];
  if (!gs.length) {
    return { ok: false, codigo: 'CLIENTE_NAO_ENCONTRADO',
      motivo: lista.map((d) => formatarDoc(d.valor)).join(', ') + ' nao esta(o) na planilha geral', diag };
  }

  let g;
  if (gs.length === 1) g = gs[0];
  else {
    const pagadores = gs.filter((x) => x.papeis.has('POS') && !x.papeis.has('NEG'));
    if (pagadores.length === 1 && gs.filter((x) => x.papeis.has('POS')).length === 1) g = pagadores[0];
    else {
      return { ok: false, codigo: 'MAIS_DE_UM_CLIENTE',
        motivo: 'o PDF cita ' + gs.length + ' clientes diferentes da planilha (' +
          gs.map((x) => x.docs.map((d) => formatarDoc(d.valor)).join('+')).join(' / ') + ') sem indicar qual e o pagador', diag };
    }
  }

  if (g.papeis.has('NEG') && !g.papeis.has('POS')) {
    return { ok: false, codigo: 'DUVIDA_TITULAR',
      motivo: formatarDoc(g.docs[0].valor) + ' aparece como beneficiario/emitente, nao como pagador', diag };
  }
  const pagadorFora = naoCasados.filter((d) => d.papeis.has('POS') && !d.papeis.has('NEG'));
  if (pagadorFora.length && !g.papeis.has('POS')) {
    return { ok: false, codigo: 'DUVIDA_TITULAR',
      motivo: 'o pagador/contribuinte ' + formatarDoc(pagadorFora[0].valor) + ' nao esta na planilha e ' +
        formatarDoc(g.docs[0].valor) + ' nao aparece como pagador', diag };
  }

  // nome do arquivo: nao identifica ninguem, mas pode desmentir
  const noNome = [];
  const nomeLimpo = String(nomeArquivo || '');
  for (const m of nomeLimpo.matchAll(/(?<![0-9])(\d{14}|\d{11})(?![0-9])/g)) noNome.push(m[1]);
  for (const m of nomeLimpo.matchAll(/(\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}|\d{3}\.\d{3}\.\d{3}-\d{2})/g)) noNome.push(m[1].replace(/\D/g, ''));
  const docsDoGrupo = new Set(g.docs.map((d) => d.valor).concat(g.res.doc_linha ? [g.res.doc_linha] : []));
  for (const v of noNome) {
    const valido = v.length === 14 ? cnpjValido(v) : cpfValido(v);
    if (!valido || ignorados.has(v) || docsDoGrupo.has(v) || !base.porDoc[v]) continue;
    const outro = resolverTelefone(base.porDoc[v]);
    if (!(outro.ok && g.res.ok && outro.telefone === g.res.telefone)) {
      return { ok: false, codigo: 'DUVIDA_TITULAR',
        motivo: 'o conteudo aponta ' + formatarDoc(g.docs[0].valor) + ', mas o nome do arquivo aponta ' + formatarDoc(v), diag };
    }
  }

  if (!g.res.ok) {
    return { ok: false, codigo: g.res.codigo, motivo: formatarDoc(g.docs[0].valor) + ': ' + g.res.motivo, diag,
      cnpj: g.docs[0].valor };
  }

  // documento principal: CNPJ antes de CPF, pagador antes de neutro; raiz vira o CNPJ completo da linha
  const ordem = (d) => (d.tipo === 'CNPJ' ? 0 : d.tipo === 'CPF' ? 1 : 2) - (d.papeis.has('POS') ? 0.5 : 0);
  const principal = g.docs.slice().sort((a, b) => ordem(a) - ordem(b))[0];
  const doc = principal.tipo === 'RAIZ' ? (g.res.doc_linha || principal.valor) : principal.valor;
  return { ok: true, cnpj: doc, cliente: g.res.nome, telefone_cliente: g.res.telefone, linha_planilha: g.res.linha, diag };
}

// ----- texto: extrator nativo + OCR (quando o ramo de OCR rodou) -----
const textoPdf = typeof extraido.text === 'string' ? extraido.text : '';
const ocr = entrada.ocr_tentado ? entrada : null;
const texto = [textoPdf, ocr ? ocr.texto_ocr : ''].filter(Boolean).join('\n');
const erroDe = (e) => umaLinha((e && (e.message || e.description)) || e).slice(0, 200);
const erroLeitura = baixado.error ? 'download falhou: ' + erroDe(baixado.error)
  : extraido.error ? 'extracao falhou: ' + erroDe(extraido.error) : '';

let r;
if (!texto.replace(/\s+/g, '')) {
  r = { ok: false, codigo: 'PDF_SEM_TEXTO',
    motivo: 'nao foi possivel ler texto do PDF' + (erroLeitura ? ' (' + erroLeitura + ')' : '') +
      (ocr ? '; OCR ' + (ocr.ocr_erro || 'nao encontrou texto') : '; OCR nao executado'), diag: [] };
} else {
  r = identificar(texto, loop.arquivo);
}

// Pasta sem template (ou template reprovado) bloqueia mesmo com cliente certo.
if (r.ok && loop.template_erro) {
  const [codigo, ...resto] = loop.template_erro.split(':');
  r = Object.assign({}, r, { ok: false, codigo: codigo.trim(), motivo: resto.join(':').trim() });
}

const destino = r.ok ? (cfg.modo_teste ? cfg.telefone_teste : r.telefone_cliente) : '';
return [{ json: {
  ok: r.ok,
  motivo_codigo: r.ok ? '' : r.codigo,
  motivo: r.ok ? '' : r.motivo,
  file_id: loop.file_id, versao: loop.versao, arquivo: loop.arquivo, pasta: loop.pasta, categoria: loop.categoria,
  link_drive: loop.link_drive, template_id: loop.template_id, template_nome: loop.template_nome,
  cnpj: r.cnpj || '', cliente: r.cliente || '', telefone_cliente: r.telefone_cliente || '',
  linha_planilha: r.linha_planilha || null,
  destino, modo: cfg.modo,
  chave: loop.file_id + '|' + loop.versao + '|' + (r.ok ? destino : 'BLOQUEIO'),
  diagnostico: {
    documentos_no_texto: r.diag || [],
    caracteres_texto: texto.replace(/\s+/g, '').length,
    ocr_usado: !!ocr, ocr_ok: ocr ? ocr.ocr_ok : null, ocr_erro: ocr ? ocr.ocr_erro : '',
    erro_leitura: erroLeitura
  }
} }];

// ============================================================
// Utilitarios comuns. O build injeta este arquivo no topo de cada
// Code node que precisa dele, entao ha uma unica versao destas regras.
// ============================================================
function txt(v) { return v === undefined || v === null ? '' : String(v).trim(); }
function soDigitos(v) { return txt(v).replace(/\D+/g, ''); }
function semAcento(v) { return txt(v).normalize('NFD').replace(/[̀-ͯ]/g, ''); }
function maiusculo(v) { return semAcento(v).toUpperCase(); }
function umaLinha(v) { return txt(v).replace(/\s+/g, ' '); }
function nomePasta(v) { return maiusculo(v).replace(/[^A-Z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim(); }
// ids do Drive so tem [A-Za-z0-9_-]; conferir antes de montar consulta evita
// que um valor estranho altere a query.
const ID_DRIVE = /^[A-Za-z0-9_-]{10,}$/;
function agoraISO() { return new Date().toISOString(); }
// A API do Maxbot recusa tag_info com mais de 255 caracteres ("Tag info #1
// must be up to 255 characters", medido em 23/09/2026 - a doc fala em 1.000).
// Conta em bytes UTF-8 por seguranca (PHP), entao avisos saem sem acento.
const LIMITE_TAG_INFO = 255;
function bytesUtf8(s) {
  let n = 0;
  for (const ch of String(s)) { const c = ch.codePointAt(0); n += c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4; }
  return n;
}
function cortarBytes(s, max) {
  let out = '';
  for (const ch of String(s)) { if (bytesUtf8(out + ch) > max) break; out += ch; }
  return out;
}
function horaLocal(iso) {
  const d = iso ? new Date(iso) : new Date();
  return d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
}

// ---------- configuracao (variaveis ENVPDF_* do ambiente do n8n) ----------
// Nenhum segredo passa por aqui: o token do Maxbot fica na credencial
// "Maxbot API" do n8n e e injetado so no momento da chamada HTTP.
function lerAmbiente(nome, padrao) {
  try {
    const v = $env[nome];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  } catch (e) { /* acesso a $env bloqueado: usa o padrao */ }
  return padrao === undefined ? '' : padrao;
}
function lerBool(nome, padrao) {
  const v = lerAmbiente(nome, '').toLowerCase();
  if (v === '') return padrao;
  return ['1', 'true', 'sim', 'yes', 's'].includes(v);
}
function lerNumero(nome, padrao) {
  const v = lerAmbiente(nome, '');
  if (v === '') return padrao;
  const n = Number(v);
  return Number.isFinite(n) ? n : padrao;
}

// ---------- CPF / CNPJ ----------
function cpfValido(d) {
  if (!/^\d{11}$/.test(d) || /^(\d)\1{10}$/.test(d)) return false;
  for (let t = 9; t < 11; t++) {
    let s = 0;
    for (let i = 0; i < t; i++) s += Number(d[i]) * (t + 1 - i);
    if (((s * 10) % 11) % 10 !== Number(d[t])) return false;
  }
  return true;
}
// Aceita o CNPJ alfanumerico (12 posicoes 0-9/A-Z + 2 DV numericos):
// o valor de cada caractere e (codigo ASCII - 48), que para digitos
// coincide com o CNPJ numerico tradicional.
function cnpjValido(c) {
  if (!/^[0-9A-Z]{12}\d{2}$/.test(c) || /^(\d)\1{13}$/.test(c)) return false;
  const dv = (base) => {
    const pesos = base.length === 12 ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2] : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
    let s = 0;
    for (let i = 0; i < base.length; i++) s += (base.charCodeAt(i) - 48) * pesos[i];
    const r = s % 11;
    return r < 2 ? 0 : 11 - r;
  };
  return dv(c.slice(0, 12)) === Number(c[12]) && dv(c.slice(0, 13)) === Number(c[13]);
}
function formatarDoc(d) {
  if (/^[0-9A-Z]{14}$/.test(d)) return d.replace(/^(.{2})(.{3})(.{3})(.{4})(.{2})$/, '$1.$2.$3/$4-$5');
  if (/^\d{11}$/.test(d)) return d.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, '$1.$2.$3-$4');
  if (/^\d{8}$/.test(d)) return d.replace(/^(\d{2})(\d{3})(\d{3})$/, '$1.$2.$3') + ' (raiz)';
  return d;
}

// Celula da coluna de documento da planilha -> documento normalizado.
// Numero vindo do Sheets perde zeros a esquerda (ex.: 01234567000189 vira
// 1234567000189). Eles sao repostos pelo tamanho, e so fica o que passa no
// digito verificador. Notacao cientifica ja perdeu digitos: descartada.
function docDaCelula(v) {
  if (v === null || v === undefined || v === '') return '';
  let s;
  if (typeof v === 'number') {
    if (!Number.isInteger(v) || v <= 0) return '';
    s = String(v);
  } else {
    s = txt(v);
    if (/\d[.,]?\d*e\+?\d+$/i.test(s)) return '';
  }
  s = s.toUpperCase().replace(/[^0-9A-Z]/g, '');
  if (!s) return '';
  if (/^\d+$/.test(s)) {
    if (s.length > 14) return '';
    if (s.length === 14 || s.length >= 12) return cnpjValido(s.padStart(14, '0')) ? s.padStart(14, '0') : '';
    const cpf = s.padStart(11, '0');
    if (cpfValido(cpf)) return cpf;
    const cnpj = s.padStart(14, '0');
    return cnpjValido(cnpj) ? cnpj : '';
  }
  return s.length === 14 && cnpjValido(s) ? s : '';
}

// ---------- telefone ----------
const DDDS_VALIDOS = new Set(('11 12 13 14 15 16 17 18 19 21 22 24 27 28 31 32 33 34 35 37 38 ' +
  '41 42 43 44 45 46 47 48 49 51 53 54 55 61 62 63 64 65 66 67 68 69 71 73 74 75 77 79 ' +
  '81 82 83 84 85 86 87 88 89 91 92 93 94 95 96 97 98 99').split(' '));

// Devolve o numero com DDI 55. Nunca acrescenta digito: numero local de
// 8 digitos (fixo ou WhatsApp antigo sem o 9) segue como esta.
function normalizarTelefone(v) {
  const bruto = typeof v === 'number' ? String(v) : txt(v);
  if (!bruto) return { ok: false, motivo: 'TELEFONE_AUSENTE', bruto: '' };
  const partes = bruto.split(/[\/;,|]|\s+e\s+|\s+ou\s+/i).map(soDigitos).filter((p) => p.length >= 8);
  if (partes.length > 1) return { ok: false, motivo: 'TELEFONE_AMBIGUO', bruto, detalhe: 'mais de um numero na mesma celula' };
  let d = soDigitos(bruto).replace(/^0+/, '');
  if (!(d.startsWith('55') && (d.length === 12 || d.length === 13))) {
    if (d.length === 10 || d.length === 11) d = '55' + d;
    else return { ok: false, motivo: 'TELEFONE_INVALIDO', bruto, detalhe: d.length + ' digitos' };
  }
  const ddd = d.slice(2, 4);
  const local = d.slice(4);
  if (!DDDS_VALIDOS.has(ddd)) return { ok: false, motivo: 'TELEFONE_INVALIDO', bruto, detalhe: 'DDD ' + ddd + ' inexistente' };
  if (local.length === 9 && local[0] !== '9') return { ok: false, motivo: 'TELEFONE_INVALIDO', bruto, detalhe: 'celular de 9 digitos sem o 9 inicial' };
  return { ok: true, numero: d, bruto };
}

// ---------- registro (Data table) ----------
const TABELA_REGISTRO = 'envio_pdf_registro';
const COLUNAS_REGISTRO = ['chave', 'file_id', 'versao', 'arquivo', 'pasta', 'tipo', 'link_drive', 'cnpj',
  'cliente', 'telefone_cliente', 'destino', 'modo', 'template_id', 'estado', 'tentativas', 'maxbot_status',
  'maxbot_msg', 'maxbot_id', 'erro', 'alerta', 'arquivamento', 'execucao', 'atualizado_em'];
function linhaRegistro(base, extra) {
  const r = Object.assign({}, base || {}, extra || {});
  const out = {};
  for (const c of COLUNAS_REGISTRO) {
    if (c === 'tentativas') out[c] = Number(r[c]) || 0;
    else out[c] = umaLinha(r[c]).slice(0, 1500);
  }
  return out;
}
// ---------- respostas HTTP ----------
// Os nos HTTP rodam com fullResponse + neverError: status HTTP vira dado.
// Falha de rede/timeout chega como item com `error` (onError continua).
function corpoResposta(j) {
  if (!j) return { erro: 'sem resposta' };
  if (j.error) {
    const e = j.error;
    return { erro: umaLinha((e && (e.message || e.description)) || JSON.stringify(e)).slice(0, 300) };
  }
  const status = Number(j.statusCode) || 200;
  let body = j.body !== undefined ? j.body : j;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) {
      return { status, erro: 'resposta nao-JSON (HTTP ' + status + '): ' + umaLinha(body).slice(0, 200) };
    }
  }
  if (status >= 400) return { status, body, erro: 'HTTP ' + status + ': ' + umaLinha(JSON.stringify(body)).slice(0, 200) };
  return { status, body: body || {} };
}
function falhaDoDrive(itens, etapa) {
  const e = itens.find((i) => i.json && i.json.error);
  if (e) {
    const er = e.json.error;
    throw new Error('Falha ao consultar o Google Drive (' + etapa + '): ' +
      umaLinha((er && (er.message || er.description)) || JSON.stringify(er)).slice(0, 300));
  }
}
function idadeHoras(iso) {
  const t = Date.parse(iso || '');
  return Number.isFinite(t) ? (Date.now() - t) / 3600000 : Infinity;
}

// ============================================================
// [CTRL] Decidir
// Consulta o registro FRESCO desta chave (lido agora, nao no inicio da
// execucao) e decide:
//   ENVIAR    -> reserva a chave como ENVIANDO antes de qualquer envio
//   ALERTAR   -> bloqueio novo: registra e avisa o operador
//   REGISTRAR -> mesmo bloqueio ja avisado: so atualiza a data
//   PULAR     -> ja ACEITO / INCERTO / em andamento / tentativas esgotadas
// ============================================================
const cfg = $('[CFG] Configuração').first().json;
const I = $('[ID] Identificar cliente').first().json;
const atual = $input.all().map((i) => i.json).find((r) => r && r.chave === I.chave) || null;

const base = {
  chave: I.chave, file_id: I.file_id, versao: I.versao, arquivo: I.arquivo, pasta: I.pasta, tipo: I.categoria,
  link_drive: I.link_drive, cnpj: I.cnpj, cliente: I.cliente, telefone_cliente: I.telefone_cliente,
  destino: I.destino, modo: cfg.modo, template_id: I.template_id || '', execucao: cfg.execucao,
  atualizado_em: agoraISO(), tentativas: atual ? Number(atual.tentativas) || 0 : 0
};
const saida = (acao, extra) => [{ json: Object.assign({}, I, { acao }, extra || {}) }];

if (!I.ok) {
  const erro = I.motivo_codigo + ': ' + I.motivo;
  const jaAvisado = !!atual && atual.estado === 'BLOQUEADO' && txt(atual.erro) === umaLinha(erro).slice(0, 1500) &&
    /^ENVIADO/.test(txt(atual.alerta));
  const registro = linhaRegistro(base, { estado: 'BLOQUEADO', erro, alerta: jaAvisado ? atual.alerta : '' });
  return saida(jaAvisado ? 'REGISTRAR' : 'ALERTAR', { registro, motivo_alerta: erro });
}

if (atual) {
  if (['ACEITO', 'INCERTO', 'ENVIANDO'].includes(atual.estado)) {
    return saida('PULAR', { motivo_pulo: 'registro ja esta ' + atual.estado + ' (execucao ' + atual.execucao + ')' });
  }
  if (atual.estado === 'ERRO_ENVIO' && Number(atual.tentativas) >= cfg.max_tentativas) {
    return saida('PULAR', { motivo_pulo: 'tentativas esgotadas (' + atual.tentativas + ')' });
  }
}

const registro = linhaRegistro(base, { estado: 'ENVIANDO', tentativas: base.tentativas + 1, erro: '', alerta: '' });
return saida('ENVIAR', { registro });

