}
// Aceita o CNPJ alfanumerico (12 posicoes 0-9/A-Z + 2 DV numericos):
// o valor de cada caractere e (codigo ASCII - 48), que para digitos
// coincide com o CNPJ numerico tradicional.
function cnpjValido(c) {
  if (!/^[0-9A-Z]{12}\d{2}$/.test(c) || /^(\d)\1{13}$/.test(c)) return false;
  const dv = (base) => {
    const pesos = base.length === 12 ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2] : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
    let s = 0;
    for (let i = 0; i < base.length; i++) s += (base.charCodeAt(i) - 48) * pesos[i];
    const r = s % 11;
    return r < 2 ? 0 : 11 - r;
