  if (/^\d{8}$/.test(d)) return d.replace(/^(\d{2})(\d{3})(\d{3})$/, '$1.$2.$3') + ' (raiz)';
  return d;
}

// Celula da coluna de documento da planilha -> documento normalizado.
// Numero vindo do Sheets perde zeros a esquerda (ex.: 01234567000189 vira
// 1234567000189). Eles sao repostos pelo tamanho, e so fica o que passa no
// digito verificador. Notacao cientifica ja perdeu digitos: descartada.
function docDaCelula(v) {
  if (v === null || v === undefined || v === '') return '';
  let s;
  if (typeof v === 'number') {
    if (!Number.isInteger(v) || v <= 0) return '';
    s = String(v);
  } else {
    s = txt(v);
    if (/\d[.,]?\d*e\+?\d+$/i.test(s)) return '';
  }
  s = s.toUpperCase().replace(/[^0-9A-Z]/g, '');
  if (!s) return '';
  if (/^\d+$/.test(s)) {
    if (s.length > 14) return '';
    if (s.length === 14 || s.length >= 12) return cnpjValido(s.padStart(14, '0')) ? s.padStart(14, '0') : '';
    const cpf = s.padStart(11, '0');
    if (cpfValido(cpf)) return cpf;
    const cnpj = s.padStart(14, '0');
    return cnpjValido(cnpj) ? cnpj : '';
