const DDDS_VALIDOS = new Set(('11 12 13 14 15 16 17 18 19 21 22 24 27 28 31 32 33 34 35 37 38 ' +
  '41 42 43 44 45 46 47 48 49 51 53 54 55 61 62 63 64 65 66 67 68 69 71 73 74 75 77 79 ' +
  '81 82 83 84 85 86 87 88 89 91 92 93 94 95 96 97 98 99').split(' '));

// Devolve o numero com DDI 55. Nunca acrescenta digito: numero local de
// 8 digitos (fixo ou WhatsApp antigo sem o 9) segue como esta.
function normalizarTelefone(v) {
  const bruto = typeof v === 'number' ? String(v) : txt(v);
  if (!bruto) return { ok: false, motivo: 'TELEFONE_AUSENTE', bruto: '' };
  const partes = bruto.split(/[\/;,|]|\s+e\s+|\s+ou\s+/i).map(soDigitos).filter((p) => p.length >= 8);
  if (partes.length > 1) return { ok: false, motivo: 'TELEFONE_AMBIGUO', bruto, detalhe: 'mais de um numero na mesma celula' };
  let d = soDigitos(bruto).replace(/^0+/, '');
  if (!(d.startsWith('55') && (d.length === 12 || d.length === 13))) {
    if (d.length === 10 || d.length === 11) d = '55' + d;
    else return { ok: false, motivo: 'TELEFONE_INVALIDO', bruto, detalhe: d.length + ' digitos' };
  }
  const ddd = d.slice(2, 4);
  const local = d.slice(4);
  if (!DDDS_VALIDOS.has(ddd)) return { ok: false, motivo: 'TELEFONE_INVALIDO', bruto, detalhe: 'DDD ' + ddd + ' inexistente' };
  if (local.length === 9 && local[0] !== '9') return { ok: false, motivo: 'TELEFONE_INVALIDO', bruto, detalhe: 'celular de 9 digitos sem o 9 inicial' };
  return { ok: true, numero: d, bruto };
}

