// [LOCK] Restaurar item (apos reservar)
// O node Postgres troca o item de entrada pela linha do RETURNING. Aqui o item ORIGINAL
// ({envio, registro, ...}) volta, com a marca lock_adquirido:
//  - linha devolvida (destino + payload)  -> lock ADQUIRIDO, item = payload;
//  - erro do Postgres                      -> lock_adquirido=false e o erro segue adiante;
//  - nenhuma linha (alwaysOutputData devolve o item de entrada) -> lock EM USO por outra execucao.
const r = $input.first().json || {};
if (r.error) return [{ json: { error: r.error, lock_adquirido: false } }];
if (r.destino && r.payload) {
  const original = typeof r.payload === 'string' ? JSON.parse(r.payload) : r.payload;
  return [{ json: Object.assign({}, original, { lock_adquirido: true }) }];
}
return [{ json: Object.assign({}, r, { lock_adquirido: false }) }];

// [LOCK] Nao adquirido
// Chega aqui quando [LOCK] Reservar destino NAO devolveu o destino:
//  - o Postgres respondeu com erro  -> falha de infraestrutura: PARA a execucao (o aviso de erro geral avisa o operador);
//  - lock ja em uso por outra execucao (DUPLICADO) -> nada e enviado nem gravado:
//      * no laco de PDFs segue para o proximo arquivo;
//      * no fluxo de ERRO (aviso geral) simplesmente termina.
const e = $input.first().json || {};
if (e.error) {
  const er = e.error;
  throw new Error('Falha ao reservar o lock de envio no Postgres: ' + String((er && (er.message || er.description)) || JSON.stringify(er)).slice(0, 300));
}
const contexto = e.envio && e.envio.contexto;
if (contexto === 'erro_geral') return [];
return [{ json: Object.assign({}, e, { lock: 'DUPLICADO_IGNORADO' }) }];

// [LOCK] Retomar avaliacao
// [LOCK] Liberar destino (DELETE) devolve so {success:true}. O resultado do envio que segue
// o fluxo e o de [MAXBOT] Avaliar envio, que sempre roda antes da liberacao (cliente, alerta e erro geral).
return [{ json: $('[MAXBOT] Avaliar envio').first().json }];

// [DRIVE] Registrar arquivamento
// So chega aqui quando o estado ja e ACEITO. Sucesso: arquivamento=OK.
// Falha ao mover: arquivamento continua PENDENTE (a proxima execucao tenta
// so o movimento, sem reenviar - ver [ARQ] Buscar pendentes).
const base = $('[CTRL] Resultado do cliente').first().json.registro;
const mov = $input.first().json || {};
const falhou = !!mov.error;
return [{ json: { registro: Object.assign({}, base, {
  arquivamento: falhou ? 'PENDENTE' : 'OK',
  erro: falhou ? (base.erro ? base.erro + ' | ARQUIVAMENTO_PENDENTE: ' : 'ARQUIVAMENTO_PENDENTE: ') +
    (mov.error.message || mov.error.description || JSON.stringify(mov.error)) : base.erro
}) } }];

// [ARQ] Preparar gravação
// Roda uma vez para TODOS os itens (varias linhas PENDENTE podem chegar juntas).
// Junta cada linha original (antes do move) com o resultado do move dela.
const antes = $('[ARQ] Buscar pendentes').all();
const movs = $input.all();
return movs.map((mov, i) => {
  const base = antes[i] ? antes[i].json : {};
  const falhou = !!(mov.json && mov.json.error);
  return { json: { registro: Object.assign({}, base, { arquivamento: falhou ? 'PENDENTE' : 'OK' }) } };
});
